function findDivisors(n) {
    var divisors = [];
    for (var i = 1; i <= Math.floor(Math.sqrt(n)); i++) {
        if (n % i === 0) {
            divisors.push(i);
            if (n / i !== i && n/i !== n) {
                divisors.push(n / i);
            }
        }
    }
    return divisors;
}

